import {
  Column,
  DataType,
  Model,
  PrimaryKey,
  Table,
} from 'sequelize-typescript';
import { Sequelize } from 'sequelize';

/**
 * A seller's discount function. `shopId` is a plain id: no association to another domain's table and no foreign key
 * (IX.4). `activeStatus` is generated by the database and takes part in the pointer foreign key to the version row.
 */
@Table({
  modelName: 'ShopFunction',
  tableName: 'ShopFunction',
  timestamps: false,
})
export default class ShopFunction extends Model<
  ShopFunction,
  Partial<ShopFunction>
> {
  @PrimaryKey
  @Column({ type: DataType.UUID, defaultValue: Sequelize.literal('uuidv7()') })
  declare id: string;

  @Column({ type: DataType.UUID, allowNull: false })
  declare shopId: string;

  @Column({ type: DataType.TEXT, allowNull: false })
  declare name: string;

  @Column({ type: DataType.INTEGER, allowNull: true })
  declare activeVersion: number | null;

  @Column({ type: DataType.BOOLEAN, allowNull: false, defaultValue: true })
  declare enabled: boolean;

  @Column({ type: DataType.DATE, allowNull: false })
  declare createdAt: Date;

  @Column({ type: DataType.DATE, allowNull: false })
  declare updatedAt: Date;
}
